/* ---- wybor jezyka i podmiana tekstow w HTML ---- */
const LANG_KEY = "hf-lang";
function chosenLanguage() {
  const q = new URLSearchParams(location.search).get("lang");
  if (q && HFLang.LANGS.includes(q)) return q;
  try {
    const saved = localStorage.getItem(LANG_KEY);
    if (saved && (saved === "auto" || HFLang.LANGS.includes(saved))) return saved;
  } catch (e) { /* brak dostepu do pamieci przegladarki */ }
  return "auto";
}
let LANG_PREF = chosenLanguage();
let LANG = HFLang.detect(LANG_PREF).lang;
let LOCALE = HFLang.LOCALES[LANG];
let t = HFLang.makeTranslator(I18N, LANG);

function setLanguage(pref) {
  LANG_PREF = pref;
  try { localStorage.setItem(LANG_KEY, pref); } catch (e) { /* bez zapamietania */ }
  LANG = HFLang.detect(pref).lang;
  LOCALE = HFLang.LOCALES[LANG];
  t = HFLang.makeTranslator(I18N, LANG);
  applyStaticTexts();
}

function applyStaticTexts() {
  document.documentElement.lang = LANG;
  document.title = t("title");
  HFLang.applyDom(document, t);
  const ph = document.getElementById("thesisInput");
  if (ph) ph.placeholder = t("eg", { x: t("c2") });
  const help = document.getElementById("yearHelp");
  if (help) help.textContent = t("yearHelp", { min: YEAR_MIN, max: YEAR_MAX });
  const sel = document.getElementById("langSelect");
  if (sel) {
    const auto = HFLang.detect("auto").lang;
    sel.innerHTML = `<option value="auto">Auto · ${HFLang.NAMES[auto]}</option>` +
      HFLang.LANGS.map((l) => `<option value="${l}">${HFLang.NAMES[l]}</option>`).join("");
    sel.value = LANG_PREF;
  }
}

// zakres lat dozwolony w ustawieniach zapytania (jak w API: 1850..biezacy rok)
const YEAR_MIN = 1850;
const YEAR_MAX = new Date().getFullYear();
